with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MEMBER_NO))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as LOADING_REASON
        , SUM_INSURED as MEMBER_SUM_INSURED
        , MEDICAL_CHECKUP as PRE_POLICY_CHECKUP_INDICATOR
        , cast(null as varchar) as CORPORATE_BUFFER_AMOUNT
        , cast(null as varchar) as CUMULATIVE_BONUS_AMOUNT
        , 'BJAZ_EC_MEM_DTLS_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ec_mem_dtls_extn') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__MEMBER_NO))) as HUB_RISK_OBJECT_HK
        , LOADING_REASON as LOADING_REASON
        , SUM_INSURED as MEMBER_SUM_INSURED
        , cast(null as varchar) as PRE_POLICY_CHECKUP_INDICATOR
        , cast(null as varchar) as CORPORATE_BUFFER_AMOUNT
        , cast(null as varchar) as CUMULATIVE_BONUS_AMOUNT
        , 'BJAZ_HCF_MEMBER_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcf_member_dtls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__CONTRACT_ID_MEMBER_ID))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as LOADING_REASON
        , cast(null as varchar) as MEMBER_SUM_INSURED
        , MEDICAL_CHECKUP as PRE_POLICY_CHECKUP_INDICATOR
        , cast(null as varchar) as CORPORATE_BUFFER_AMOUNT
        , cast(null as varchar) as CUMULATIVE_BONUS_AMOUNT
        , 'BJAZ_HM_MEMBER_HLTH_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_hlth_dtls') }}
    where (nullif('MEMBER:' || coalesce(nullif(trim(CONTRACT_ID),''),'') || '#' || coalesce(nullif(trim(MEMBER_ID),''),''), 'MEMBER:#')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then LOADING_REASON end) as LOADING_REASON,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_SUM_INSURED end) as MEMBER_SUM_INSURED,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then PRE_POLICY_CHECKUP_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PRE_POLICY_CHECKUP_INDICATOR end)) as PRE_POLICY_CHECKUP_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CORPORATE_BUFFER_AMOUNT end) as CORPORATE_BUFFER_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CUMULATIVE_BONUS_AMOUNT end) as CUMULATIVE_BONUS_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK
),

hashed as (
    select
        *,
        case when LOADING_REASON is not null or MEMBER_SUM_INSURED is not null or PRE_POLICY_CHECKUP_INDICATOR is not null or CORPORATE_BUFFER_AMOUNT is not null or CUMULATIVE_BONUS_AMOUNT is not null
                     then md5(upper(coalesce(cast(LOADING_REASON as varchar), '') || '|' || coalesce(cast(MEMBER_SUM_INSURED as varchar), '') || '|' || coalesce(cast(PRE_POLICY_CHECKUP_INDICATOR as varchar), '') || '|' || coalesce(cast(CORPORATE_BUFFER_AMOUNT as varchar), '') || '|' || coalesce(cast(CUMULATIVE_BONUS_AMOUNT as varchar), '')))
                end as SAT_RISK_HEALTH_MEMBER_COVERAGE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_HEALTH_MEMBER_COVERAGE_HASHDIFF is not null
